/**
 * REPLAY COPY GENERATED BY V9_9_2_1_1_REPLAY_LAUNCHER_WITH_V9_8_REPAIRED_CARRY_FORWARD_BRIDGE
 * Source business logic: scripts/v9902-1-1.cjs
 * Historical versions are NOT spoofed.
 * V9.8 physical 028080 repair remains a separate virtual overlay.
 */

/* eslint-disable no-console */
'use strict';

/**
 * AI Stock Lab
 * V9.9.2.1 - New incremental workset + prior carry-forward reconciliation
 *
 * READ-ONLY.
 * - no network
 * - no DB writes
 *
 * Inputs:
 *   logs/opendart-corporate-action-detail-workset-v9-9-2.json
 *   logs/opendart-corporate-action-cycle-closure-v9-8-11-13-replay-v2-v9-9-bridge.json
 *
 * Output:
 *   logs/opendart-corporate-action-workset-carryforward-reconciliation-v9-9-2-1.json
 *
 * Purpose:
 *   1) Preserve all 55 prior carry-forward items.
 *   2) Add the 7 new in-contract candidates from 2026-10-02..2026-10-04.
 *   3) Detect overlaps between new candidates and carry-forward by:
 *        - providerEventId / receipt identity
 *        - stockCode + actionType
 *   4) Split:
 *        - new standalone candidates
 *        - possible carry-forward corrections/reconfirmations
 *        - carry-forward items untouched by this incremental window
 *   5) Never mutate production state here.
 */

const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const VERSION =
  'V9_9_2_1_1_REPLAY_INCREMENTAL_WORKSET_CARRY_FORWARD_RECONCILIATION_FIELD_PATH_REPAIR';

const EXPECTED_WORKSET_VERSION =
  'V9_8_2_INCREMENTAL_CORPORATE_ACTION_DETAIL_WORKSET';

const EXPECTED_CLOSURE_VERSION =
  'V9_8_11_13_REPLAY_V2_V9_9_CARRY_FORWARD_BRIDGE';

const EXPECTED_NEW_SOURCE_CANDIDATES = 15;
const EXPECTED_NEW_IN_CONTRACT = 7;
const EXPECTED_PRIOR_FUTURE_RATIO = 24;
const EXPECTED_PRIOR_FUTURE_STRUCTURAL = 30;
const EXPECTED_PRIOR_FUTURE_CASH = 1;
const EXPECTED_PRIOR_CARRY_FORWARD = 55;

function readJson(file) {
  return JSON.parse(
    fs.readFileSync(file, 'utf8').replace(/^\uFEFF/, ''),
  );
}

function atomicSave(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const tmp = `${file}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(value, null, 2), 'utf8');
  fs.renameSync(tmp, file);
}

function sha256(value) {
  return crypto
    .createHash('sha256')
    .update(value)
    .digest('hex');
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return null;
}

function normalizeActionType(value) {
  return String(value ?? '')
    .trim()
    .toUpperCase();
}

function normalizeStockCode(value) {
  return String(value ?? '')
    .trim();
}

function normalizeReceipt(value) {
  return String(value ?? '')
    .trim();
}

function normalizeNewRow(row) {
  const providerEventId =
    normalizeReceipt(
      firstNonEmpty(
        row.providerEventId,
        row.provider_event_id,
        row.receiptNo,
        row.receipt_no,
        row.rcept_no,
        row.sourceReceiptNo,
        row.source_receipt_no,
      ),
    );

  const receiptNo =
    normalizeReceipt(
      firstNonEmpty(
        row.receiptNo,
        row.receipt_no,
        row.rcept_no,
        row.sourceReceiptNo,
        row.source_receipt_no,
        row.providerEventId,
        row.provider_event_id,
      ),
    );

  const stockCode =
    normalizeStockCode(
      firstNonEmpty(
        row.stockCode,
        row.stock_code,
      ),
    );

  const actionType =
    normalizeActionType(
      firstNonEmpty(
        row.actionType,
        row.action_type,
      ),
    );

  return {
    providerEventId,
    receiptNo,
    stockCode,
    actionType,

    gate:
      row.gate ?? null,

    isCorrectionOrWithdrawal:
      Boolean(
        row.isCorrectionOrWithdrawal ??
        row.is_correction_or_withdrawal ??
        row.correction ??
        row.withdrawal ??
        row.needsChainLookup ??
        false
      ),

    needsChainLookup:
      Boolean(
        row.needsChainLookup ??
        false
      ),

    canBecomeProductionEvent:
      Boolean(
        row.canBecomeProductionEvent ??
        false
      ),

    autoDetailFetch:
      Boolean(
        row.autoDetailFetch ??
        false
      ),

    raw:
      row,
  };
}

function normalizeCarryRow(
  row,
  category,
) {
  return {
    category,

    providerEventId:
      normalizeReceipt(
        firstNonEmpty(
          row.providerEventId,
          row.provider_event_id,
        ),
      ),

    stockCode:
      normalizeStockCode(
        firstNonEmpty(
          row.stockCode,
          row.stock_code,
        ),
      ),

    actionType:
      normalizeActionType(
        firstNonEmpty(
          row.actionType,
          row.action_type,
          category === 'FUTURE_CASH'
            ? 'CASH_DIVIDEND'
            : null,
        ),
      ),

    effectiveDate:
      firstNonEmpty(
        row.effectiveDate,
        row.effective_date,
      ),

    priorDisposition:
      firstNonEmpty(
        row.disposition,
        row.status,
      ),

    raw:
      row,
  };
}

function main() {
  const root =
    path.resolve(__dirname, '..');

  const worksetFile =
    path.join(
      root,
      'logs',
      'opendart-corporate-action-detail-workset-v9-9-2.json',
    );

  const closureFile =
    path.join(
      root,
      'logs',
      'opendart-corporate-action-cycle-closure-v9-8-11-13-replay-v2-v9-9-bridge.json',
    );

  const outputFile =
    path.join(
      root,
      'logs',
      'opendart-corporate-action-workset-carryforward-reconciliation-v9-9-2-1-1-replay.json',
    );

  if (!fs.existsSync(worksetFile)) {
    throw new Error('WORKSET_INPUT_NOT_FOUND');
  }

  if (!fs.existsSync(closureFile)) {
    throw new Error('CLOSURE_INPUT_NOT_FOUND');
  }

  const workset =
    readJson(worksetFile);

  const closure =
    readJson(closureFile);

  if (
    workset.version !==
    EXPECTED_WORKSET_VERSION
  ) {
    throw new Error(
      'WORKSET_VERSION_MISMATCH',
    );
  }

  if (
    workset.status !==
    'DETAIL_WORKSET_READY'
  ) {
    throw new Error(
      'WORKSET_NOT_READY',
    );
  }

  if (
    closure.version !==
    EXPECTED_CLOSURE_VERSION
  ) {
    throw new Error(
      'CLOSURE_VERSION_MISMATCH',
    );
  }

  if (
    closure.status !==
    'V9_8_CURRENT_CYCLE_CLOSED_AT_2026_10_01'
  ) {
    throw new Error(
      'PRIOR_CYCLE_NOT_CLOSED',
    );
  }

  const sourceCandidates =
    Number(
      workset.counts?.sourceCandidates ??
      workset.source?.sourceCandidateCount ??
      workset.source?.candidateCount ??
      workset.sourceCandidates ??
      workset.summary?.sourceCandidates ??
      0,
    );

  const allRows =
    Array.isArray(workset.allRows)
      ? workset.allRows
      : [];

  if (
    sourceCandidates !==
    EXPECTED_NEW_SOURCE_CANDIDATES
  ) {
    throw new Error(
      `EXPECTED_15_SOURCE_CANDIDATES_GOT_${sourceCandidates}`,
    );
  }

  if (
    allRows.length !==
    EXPECTED_NEW_SOURCE_CANDIDATES
  ) {
    throw new Error(
      `EXPECTED_15_WORKSET_ROWS_GOT_${allRows.length}`,
    );
  }

  const newInContract =
    allRows
      .filter(
        (row) =>
          row.gate !==
          'OUT_OF_CURRENT_CANONICAL_SCOPE',
      )
      .map(
        normalizeNewRow,
      );

  if (
    newInContract.length !==
    EXPECTED_NEW_IN_CONTRACT
  ) {
    throw new Error(
      `EXPECTED_7_IN_CONTRACT_GOT_${newInContract.length}`,
    );
  }

  const futureRatio =
    Array.isArray(
      closure.carryForward
        ?.futureRatioActions,
    )
      ? closure.carryForward
          .futureRatioActions
          .map(
            (row) =>
              normalizeCarryRow(
                row,
                'FUTURE_RATIO',
              ),
          )
      : [];

  const futureStructuralSource =
    closure.carryForward
      ?.futureStructuralActions;

  /*
   * v9.8 closure intentionally summarized future structural items
   * as count-only. For reconciliation, recover detailed rows from the
   * snapshot eligibility output if needed.
   */
  let futureStructural = [];

  const snapshotEligibilityFile =
    path.join(
      root,
      'logs',
      'opendart-corporate-action-snapshot-eligibility-v9-8-11-5-1.json',
    );

  if (
    fs.existsSync(
      snapshotEligibilityFile,
    )
  ) {
    const snapshot =
      readJson(
        snapshotEligibilityFile,
      );

    const deferredRows =
      Array.isArray(
        snapshot.deferredFutureStructuralRows,
      )
        ? snapshot.deferredFutureStructuralRows
        : Array.isArray(
            snapshot.deferredRows,
          )
          ? snapshot.deferredRows
          : Array.isArray(
              snapshot.deferredFutureStructural,
            )
            ? snapshot.deferredFutureStructural
            : [];

    futureStructural =
      deferredRows.map(
        (row) =>
          normalizeCarryRow(
            row,
            'FUTURE_STRUCTURAL',
          ),
      );
  }

  const futureCashRaw =
    closure.carryForward
      ?.futureCashDividend;

  const futureCash =
    futureCashRaw
      ? [
          normalizeCarryRow(
            futureCashRaw,
            'FUTURE_CASH',
          ),
        ]
      : [];

  if (
    futureRatio.length !==
    EXPECTED_PRIOR_FUTURE_RATIO
  ) {
    throw new Error(
      `EXPECTED_24_FUTURE_RATIO_GOT_${futureRatio.length}`,
    );
  }

  if (
    Number(
      futureStructuralSource
        ?.count ??
      futureStructural.length,
    ) !==
    EXPECTED_PRIOR_FUTURE_STRUCTURAL
  ) {
    throw new Error(
      'EXPECTED_30_FUTURE_STRUCTURAL_COUNT',
    );
  }

  if (
    futureStructural.length !==
    EXPECTED_PRIOR_FUTURE_STRUCTURAL
  ) {
    throw new Error(
      `EXPECTED_30_FUTURE_STRUCTURAL_DETAIL_ROWS_GOT_${futureStructural.length}`,
    );
  }

  if (
    futureCash.length !==
    EXPECTED_PRIOR_FUTURE_CASH
  ) {
    throw new Error(
      `EXPECTED_1_FUTURE_CASH_GOT_${futureCash.length}`,
    );
  }

  const carryForward =
    [
      ...futureRatio,
      ...futureStructural,
      ...futureCash,
    ];

  if (
    carryForward.length !==
    EXPECTED_PRIOR_CARRY_FORWARD
  ) {
    throw new Error(
      `EXPECTED_55_CARRY_FORWARD_GOT_${carryForward.length}`,
    );
  }

  const carryByProviderEventId =
    new Map();

  const carryByStockAction =
    new Map();

  for (
    const row of
    carryForward
  ) {
    if (
      row.providerEventId
    ) {
      const existing =
        carryByProviderEventId
          .get(
            row.providerEventId,
          ) ??
        [];

      existing.push(row);

      carryByProviderEventId
        .set(
          row.providerEventId,
          existing,
        );
    }

    if (
      row.stockCode &&
      row.actionType
    ) {
      const key =
        `${row.stockCode}|${row.actionType}`;

      const existing =
        carryByStockAction
          .get(key) ??
        [];

      existing.push(row);

      carryByStockAction
        .set(
          key,
          existing,
        );
    }
  }

  const reconciledNewRows =
    newInContract.map(
      (row) => {
        const exactIdentityMatches =
          [
            ...(
              row.providerEventId
                ? (
                    carryByProviderEventId
                      .get(
                        row.providerEventId,
                      ) ??
                    []
                  )
                : []
            ),

            ...(
              row.receiptNo &&
              row.receiptNo !==
                row.providerEventId
                ? (
                    carryByProviderEventId
                      .get(
                        row.receiptNo,
                      ) ??
                    []
                  )
                : []
            ),
          ];

        const uniqueExact =
          [
            ...new Map(
              exactIdentityMatches
                .map(
                  (item) => [
                    `${item.category}|${item.providerEventId}|${item.stockCode}|${item.actionType}`,
                    item,
                  ],
                ),
            ).values(),
          ];

        const stockActionMatches =
          row.stockCode &&
          row.actionType
            ? (
                carryByStockAction
                  .get(
                    `${row.stockCode}|${row.actionType}`,
                  ) ??
                []
              )
            : [];

        const likelyCarryForwardRelated =
          uniqueExact.length >
            0 ||
          stockActionMatches.length >
            0 ||
          row.needsChainLookup;

        let disposition;

        if (
          uniqueExact.length >
          0
        ) {
          disposition =
            'EXACT_CARRY_FORWARD_IDENTITY_RECONFIRM';
        } else if (
          stockActionMatches.length >
          0
        ) {
          disposition =
            'POSSIBLE_CARRY_FORWARD_CORRECTION_OR_RECONFIRMATION';
        } else if (
          row.needsChainLookup
        ) {
          disposition =
            'NEW_CORRECTION_CHAIN_LOOKUP_REQUIRED';
        } else {
          disposition =
            'NEW_STANDALONE_DETAIL_FETCH';
        }

        return {
          providerEventId:
            row.providerEventId,

          receiptNo:
            row.receiptNo,

          stockCode:
            row.stockCode,

          actionType:
            row.actionType,

          gate:
            row.gate,

          needsChainLookup:
            row.needsChainLookup,

          autoDetailFetch:
            row.autoDetailFetch,

          canBecomeProductionEvent:
            row.canBecomeProductionEvent,

          exactCarryForwardIdentityMatches:
            uniqueExact.map(
              (item) => ({
                category:
                  item.category,

                providerEventId:
                  item.providerEventId,

                stockCode:
                  item.stockCode,

                actionType:
                  item.actionType,

                effectiveDate:
                  item.effectiveDate,

                priorDisposition:
                  item.priorDisposition,
              }),
            ),

          stockActionCarryForwardMatches:
            stockActionMatches.map(
              (item) => ({
                category:
                  item.category,

                providerEventId:
                  item.providerEventId,

                stockCode:
                  item.stockCode,

                actionType:
                  item.actionType,

                effectiveDate:
                  item.effectiveDate,

                priorDisposition:
                  item.priorDisposition,
              }),
            ),

          likelyCarryForwardRelated,

          disposition,
        };
      },
    );

  const matchedCarryForwardKeys =
    new Set();

  for (
    const row of
    reconciledNewRows
  ) {
    for (
      const match of
      [
        ...row
          .exactCarryForwardIdentityMatches,
        ...row
          .stockActionCarryForwardMatches,
      ]
    ) {
      matchedCarryForwardKeys.add(
        `${match.category}|${match.providerEventId}|${match.stockCode}|${match.actionType}`,
      );
    }
  }

  const untouchedCarryForward =
    carryForward
      .filter(
        (row) =>
          !matchedCarryForwardKeys
            .has(
              `${row.category}|${row.providerEventId}|${row.stockCode}|${row.actionType}`,
            ),
      )
      .map(
        (row) => ({
          category:
            row.category,

          providerEventId:
            row.providerEventId,

          stockCode:
            row.stockCode,

          actionType:
            row.actionType,

          effectiveDate:
            row.effectiveDate,

          priorDisposition:
            row.priorDisposition,

          disposition:
            'CARRY_FORWARD_UNTOUCHED_BY_2026_10_02_TO_2026_10_04_INCREMENTAL_WINDOW',
        }),
      );

  const exactCarryForwardMatches =
    reconciledNewRows.filter(
      (row) =>
        row
          .exactCarryForwardIdentityMatches
          .length >
        0,
    );

  const stockActionCarryForwardMatches =
    reconciledNewRows.filter(
      (row) =>
        row
          .exactCarryForwardIdentityMatches
          .length ===
          0 &&
        row
          .stockActionCarryForwardMatches
          .length >
          0,
    );

  const newChainLookupOnly =
    reconciledNewRows.filter(
      (row) =>
        row.disposition ===
        'NEW_CORRECTION_CHAIN_LOOKUP_REQUIRED',
    );

  const newStandalone =
    reconciledNewRows.filter(
      (row) =>
        row.disposition ===
        'NEW_STANDALONE_DETAIL_FETCH',
    );

  const blockers = [];

  if (
    newInContract.length !==
    reconciledNewRows.length
  ) {
    blockers.push(
      'NEW_WORKSET_RECONCILIATION_ACCOUNTING_MISMATCH',
    );
  }

  if (
    carryForward.length !==
    matchedCarryForwardKeys.size +
      untouchedCarryForward.length
  ) {
    blockers.push(
      'CARRY_FORWARD_ACCOUNTING_MISMATCH',
    );
  }

  const status =
    blockers.length === 0
      ? 'WORKSET_CARRY_FORWARD_RECONCILIATION_READY'
      : 'WORKSET_CARRY_FORWARD_RECONCILIATION_BLOCKED';

  const report = {
    version:
      VERSION,

    status,

    source: {
      worksetVersion:
        workset.version,

      worksetFingerprint:
        workset.outputFingerprint ??
        null,

      priorClosureVersion:
        closure.version,

      priorClosureFingerprint:
        closure.outputFingerprint ??
        null,

      incrementalWindow: {
        startDate:
          workset.source
            ?.startDate ??
          null,

        throughDate:
          workset.source
            ?.throughDate ??
          null,
      },
    },

    counts: {
      newSourceCandidates:
        sourceCandidates,

      newInCurrentCanonicalContract:
        newInContract.length,

      newOutOfScope:
        allRows.length -
        newInContract.length,

      priorFutureRatio:
        futureRatio.length,

      priorFutureStructural:
        futureStructural.length,

      priorFutureCash:
        futureCash.length,

      priorCarryForwardTotal:
        carryForward.length,

      exactCarryForwardIdentityNewRows:
        exactCarryForwardMatches.length,

      stockActionCarryForwardRelatedNewRows:
        stockActionCarryForwardMatches.length,

      newCorrectionChainLookupOnly:
        newChainLookupOnly.length,

      newStandaloneDetailFetch:
        newStandalone.length,

      touchedCarryForwardItems:
        matchedCarryForwardKeys.size,

      untouchedCarryForwardItems:
        untouchedCarryForward.length,

      blockers:
        blockers.length,
    },

    blockers,

    newRows:
      reconciledNewRows,

    touchedCarryForward: [
      ...matchedCarryForwardKeys,
    ],

    untouchedCarryForward,

    queues: {
      detailFetchQueue:
        reconciledNewRows
          .filter(
            (row) =>
              row.autoDetailFetch,
          ),

      chainLookupQueue:
        reconciledNewRows
          .filter(
            (row) =>
              row.needsChainLookup ||
              row
                .exactCarryForwardIdentityMatches
                .length >
                0 ||
              row
                .stockActionCarryForwardMatches
                .length >
                0,
          ),

      standaloneNewQueue:
        newStandalone,

      carryForwardReconfirmationQueue:
        reconciledNewRows
          .filter(
            (row) =>
              row
                .exactCarryForwardIdentityMatches
                .length >
                0 ||
              row
                .stockActionCarryForwardMatches
                .length >
                0,
          ),
    },

    safety: {
      networkRequests:
        0,

      databaseWrites:
        0,

      productionApplied:
        false,

      canonicalEventsCreated:
        0,

      adjustmentRunsCreated:
        0,

      factorsCreated:
        0,

      marketDailyBarsModified:
        0,

      coverageWindowAdvanced:
        false,
    },

    nextGate:
      status ===
      'WORKSET_CARRY_FORWARD_RECONCILIATION_READY'
        ? 'BUILD_V9_9_DETAIL_EVIDENCE_FETCH_AND_CHAIN_RECONFIRMATION'
        : 'STOP_AND_REVIEW',

    outputFile:
      path
        .relative(
          root,
          outputFile,
        )
        .replaceAll(
          '\\',
          '/',
        ),
  };

  report.outputFingerprint =
    sha256(
      JSON.stringify({
        version:
          report.version,

        status:
          report.status,

        worksetFingerprint:
          report.source
            .worksetFingerprint,

        priorClosureFingerprint:
          report.source
            .priorClosureFingerprint,

        newRows:
          report.newRows.map(
            (row) => [
              row.providerEventId,
              row.receiptNo,
              row.stockCode,
              row.actionType,
              row.disposition,
            ],
          ),

        untouchedCarryForward:
          report.untouchedCarryForward.map(
            (row) => [
              row.category,
              row.providerEventId,
              row.stockCode,
              row.actionType,
              row.effectiveDate,
            ],
          ),
      }),
    );

  atomicSave(
    outputFile,
    report,
  );

  console.log(
    JSON.stringify(
      {
        status:
          report.status,

        version:
          VERSION,

        ...report.counts,

        blockers:
          report.blockers,

        carryForwardReconfirmationQueue:
          report.queues
            .carryForwardReconfirmationQueue
            .map(
              (row) => ({
                providerEventId:
                  row.providerEventId,

                receiptNo:
                  row.receiptNo,

                stockCode:
                  row.stockCode,

                actionType:
                  row.actionType,

                disposition:
                  row.disposition,
              }),
            ),

        networkRequests:
          0,

        databaseWrites:
          0,

        nextGate:
          report.nextGate,

        outputFile:
          report.outputFile,
      },
      null,
      2,
    ),
  );

  if (
    status !==
    'WORKSET_CARRY_FORWARD_RECONCILIATION_READY'
  ) {
    process.exitCode =
      2;
  }
}

try {
  main();
} catch (error) {
  console.error(
    JSON.stringify(
      {
        status:
          'WORKSET_CARRY_FORWARD_RECONCILIATION_FAILED',

        version:
          VERSION,

        error:
          String(
            error?.message ??
            error,
          ),

        networkRequests:
          0,

        databaseWrites:
          0,

        coverageWindowAdvanced:
          false,
      },
      null,
      2,
    ),
  );

  process.exitCode =
    1;
}
